python - <<'PY'
import json,numpy as np
p=json.load(open('/app/output/planproto.json'))
for box in [0,1,2]:
 lens=[]
 for s in p:
  a=np.array(s['a']);b=np.array(s['b']);d=b-a;t0,t1=0.,1.
  for j in range(2):
   if abs(d[j])<1e-9:
    if a[j]<box or a[j]>64-box:t0,t1=1,0
   else:
    x1=(box-a[j])/d[j];x2=(64-box-a[j])/d[j];t0=max(t0,min(x1,x2));t1=min(t1,max(x1,x2))
    if t0>t1:break
  lens.append(np.linalg.norm(d)*(t1-t0) if t0<=t1 else 0)
 print('box',box,'<3px',sum(l<3 for l in lens),'median',np.median(lens),'sum',sum(lens))
PY

